/**
 * Gabungkan label inti + label Auth/Profil/Pengaturan untuk bahasa aktif.
 * Bahasa tanpa entri di kamus ini (mis. fil/sw) otomatis fallback ke Inggris.
 */
export function mergeLabels(
  base: Record<string, string>,
  language: LanguageCode,
): Record<string, string> {
  const extra: Record<string, string> = dictAuthProfile[language] ?? dictAuthProfile.en;
  return { ...base, ...extra };
}
